mapper.select:
select  from takeout_product p
left join takeout_merchant m on m.merchant_id = p.merchant_id
where p.del_flag = '0'
and p.product_id = #{productId}
and p.merchant_id = #{merchantId}
and p.product_name like concat('%', #{productName}, '%')
and p.category_name = #{categoryName}
and p.status = #{status}
order by p.create_time desc, p.product_id desc

mapper.update:
update takeout_product
product_name = #{productName}, category_name = #{categoryName}, price = #{price}, image = #{image}, description = #{description}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate(), version = version + 1
where product_id = #{productId} and del_flag = '0' and version = #{version}

update takeout_product set status = #{status}, update_by = #{updateBy},
    update_time = sysdate(), version = version + 1
where product_id = #{productId} and del_flag = '0' and version = #{version}
